// Fake Baileys for tests/test_wa_pace.py. FAKE_WA: ok | 403 | 503after1. FAKE_CALLS: file, one JSON line per connect/lookup.
import fs from 'node:fs'
import path from 'node:path'
const MODE = process.env.FAKE_WA || 'ok'
const note = o => process.env.FAKE_CALLS && fs.appendFileSync(process.env.FAKE_CALLS, JSON.stringify(o) + '\n')
export const DisconnectReason = { loggedOut: 401 }
export async function fetchLatestBaileysVersion() { return { version: [2, 3000, 1] } }
export async function useMultiFileAuthState(dir) {
  fs.mkdirSync(dir, { recursive: true })
  const f = path.join(dir, 'creds.json')
  const creds = fs.existsSync(f) ? JSON.parse(fs.readFileSync(f, 'utf8')) : {}
  return { state: { creds, keys: {} }, saveCreds: async () => {} }
}
function makeWASocket(opts) {
  note({ connect: Date.now() })
  const h = {}
  const emit = (e, v) => (h[e] || []).forEach(f => f(v))
  const close = code => emit('connection.update', { connection: 'close', lastDisconnect: { error: Object.assign(
    new Error(code === 403 ? 'Connection Failure' : 'Stream Errored (unknown)'), { output: { statusCode: code }, data: { reason: String(code), location: 'test' } }) } })
  let n = 0
  const sock = {
    ev: { on: (e, f) => (h[e] ||= []).push(f) },
    ws: { on() {} },
    sendNode: async () => {}, end() {}, logout: async () => {},
    async onWhatsApp(...nums) {
      n++; note({ call: Date.now(), nums })
      if (MODE === '503after1' && n === 1) setTimeout(() => close(503), 10)
      return nums.map(x => ({ jid: x + '@s.whatsapp.net', exists: x.endsWith('1') }))
    }
  }
  setTimeout(() => {
    if (!opts.auth.creds.me) return emit('connection.update', { qr: 'ref,a,b,c,d' })
    if (MODE === '403') return close(403)
    emit('connection.update', { connection: 'open' })
  }, 20)
  return sock
}
export default makeWASocket
